const input = $json ?? {};
const deal = input.deal ?? input.transaction ?? input;
const recovery = input.recovery ?? input.resolution ?? {};
const readiness = input.transaction_readiness ?? deal.transaction_readiness ?? {};
const docs = Array.isArray(readiness.required_documents) ? readiness.required_documents : [];
const missingDocs = docs.filter(d => {
  const s = String(d?.status ?? '').toLowerCase();
  return !['complete','completed','received','verified','approved'].includes(s);
});
const blockers = [
  ...(Array.isArray(deal.blockers) ? deal.blockers : []),
  ...(Array.isArray(readiness.blockers) ? readiness.blockers : [])
].filter(Boolean);

const identityComplete = Boolean(deal.deal_id ?? deal.transaction_id) &&
  Boolean(deal.property_id) &&
  Boolean(deal.lead_id ?? deal.seller_id);
const executed = String(deal.execution_state ?? deal.agreement?.execution_state ?? '').toLowerCase() === 'executed';
const signedEvidence = Boolean(deal.signed_evidence ?? deal.agreement?.signed_evidence);
const recoveryStatus = String(recovery.status ?? '').toLowerCase();
const recoveryEvidence = Boolean(recovery.evidence ?? recovery.evidence_url ?? recovery.confirmation);
const closingDate = readiness.closing_date ?? deal.closing_date ?? deal.critical_dates?.closing_date ?? null;
const closingDateValid = Boolean(closingDate && !Number.isNaN(new Date(closingDate).getTime()));

const partyReady = (x) => Boolean(x?.ready ?? x?.confirmed ?? String(x?.status ?? '').toLowerCase() === 'ready');
const partiesReady = {
  title: partyReady(readiness.title ?? deal.title),
  attorney: partyReady(readiness.attorney ?? deal.attorney),
  funding: partyReady(readiness.funding ?? deal.funding),
  buyer: partyReady(readiness.buyer ?? deal.buyer)
};

let status = 'not_ready';
let severity = 'high';
if (!identityComplete || !executed || !signedEvidence) {
  status = 'blocked';
  severity = 'urgent';
} else if (['failed','rejected','cancelled','terminated'].includes(recoveryStatus)) {
  status = 'blocked';
  severity = 'urgent';
} else if (missingDocs.length || blockers.length || !Object.values(partiesReady).every(Boolean) || !closingDateValid) {
  status = 'needs_reconciliation';
  severity = 'high';
} else if (['recovered','resolved','completed','cleared'].includes(recoveryStatus) || recoveryEvidence) {
  status = 'ready_for_closing_coordination';
  severity = 'normal';
}

const routing = status === 'ready_for_closing_coordination'
  ? {next_workflow:'WF-126',reason:'Recovery is complete and transaction readiness reconciles successfully.'}
  : status === 'needs_reconciliation'
    ? {next_workflow:'WF-155',reason:'Transaction readiness gaps remain; continue closing coordination.'}
    : {next_workflow:'WF-126',reason:'Blocking condition requires closing coordination or human escalation.'};

return [{
  json:{
    ...input,
    workflow_id:'WF-175',
    workflow_name:'Closing Recovery Completion → Transaction Readiness Reconciliation',
    decision:{status,severity},
    identity_complete:identityComplete,
    execution_state:deal.execution_state ?? deal.agreement?.execution_state ?? null,
    signed_evidence_present:signedEvidence,
    recovery_status:recoveryStatus || null,
    recovery_evidence_present:recoveryEvidence,
    required_document_count:docs.length,
    missing_document_count:missingDocs.length,
    missing_documents:missingDocs.map(d => ({id:d?.id ?? null,name:d?.name ?? null,status:d?.status ?? null})),
    blockers,
    parties_ready:partiesReady,
    closing_date:closingDate,
    closing_date_valid:closingDateValid,
    routing
  }
}];

const out = $json ?? {};
return [{
  json:{
    ...out,
    workflow_id:'WF-175',
    result:'transaction_readiness_reconciled',
    next_workflow:out.routing?.next_workflow ?? 'WF-126'
  }
}];
